import React from "react";

class SpecialistsSection extends React.Component {
  formatDate = (date) => {
    if (!date) {
      return null;
    }

    const value = new Date(date);

    if (Number.isNaN(value.getTime())) {
      return date;
    }

    return value.toLocaleDateString("fa-IR", {
      weekday: "long",
      month: "long",
      day: "numeric",
    });
  };

  formatTime = (time) => {
    if (!time) {
      return "";
    }

    return String(time).substring(0, 5);
  };

  getInitials = (person) => {
    const first =
      person.first_name?.charAt(0) || "";

    const last =
      person.last_name?.charAt(0) || "";

    return `${first}${last}`;
  };

  getFullName = (person) => {
    return `${person.first_name || ""} ${
      person.last_name || ""
    }`.trim();
  };

  render() {
    const {
      specialists = [],
      onViewProfile,
    } = this.props;

    return (
      <>
        <div className="detail-divider"></div>

        <h3 className="detail-h2">
          متخصصین موجود
        </h3>

        {specialists.length === 0 ? (
          <div className="spec-empty">
            متخصصی برای این خدمت ثبت نشده است.
          </div>
        ) : (
          <div className="spec-list">

            {specialists.map((spec) => {
              const name =
                this.getFullName(spec);

              const initials =
                this.getInitials(spec);

              const appointment =
                spec.next_appointment;

              return (
                <div
                  className="spec-item"
                  key={spec.id}
                >

                  <div className="spec-item-top">

                    <div className="spec-item-avatar">
                      {spec.avatar ? (
                        <img
                          src={spec.avatar}
                          alt={name}
                        />
                      ) : (
                        initials
                      )}
                    </div>

                    <div className="spec-item-info">

                      <div className="spec-item-name">
                        {name}
                      </div>

                      <div className="spec-item-role">
                        {skill}
                      </div>

                    </div>

                    <button
                      type="button"
                      className="spec-view-btn"
                      onClick={() =>
                        onViewProfile &&
                        onViewProfile(spec)
                      }
                    >
                      مشاهده پروفایل
                    </button>

                  </div>

                  <div className="spec-item-rate">

                    <svg
                      width="13"
                      height="13"
                      viewBox="0 0 24 24"
                      fill="currentColor"
                    >
                      <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z" />
                    </svg>

                    —

                    <span
                      style={{
                        color: "var(--ink-3)",
                      }}
                    >
                      (۰)
                    </span>

                  </div>

                  <div className="spec-item-div"></div>

                  <div className="spec-item-next">

                    <svg
                      width="14"
                      height="14"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <rect
                        x="3"
                        y="4"
                        width="18"
                        height="18"
                        rx="2"
                      />

                      <path d="M16 2v4M8 2v4M3 10h18" />
                    </svg>

                    نوبت بعدی:

                    <b>
                      {appointment ? (
                        <>
                          {this.formatDate(
                            appointment.appointment_date
                          )}

                          {"، ساعت "}

                          {this.formatTime(
                            appointment.appointment_time
                          )}
                        </>
                      ) : (
                        "نوبتی ثبت نشده"
                      )}
                    </b>

                  </div>

                </div>
              );
            })}

          </div>
        )}
      </>
    );
  }
}

export default SpecialistsSection;
